package com.vandorlabs.client;
import com.vandorlabs.redstone.TransmitterSlots;
import com.vandorlabs.items.ItemRedstoneTransmitter;
import net.minecraft.nbt.*;
/** Actual installed development transmitter wrappers upgraded into row and main settings. */
public final class ScreenTransmissionLegacyChecks {
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(new ItemRedstoneTransmitter());java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0;for(String slot:new String[]{"main","row_0_0","row_1_1","row_9_0","row_bad"})for(int count=0;count<2;count++)for(int damage:new int[]{-1,0,1,2,3,4,32767})for(int existing=0;existing<3;existing++){NBTTagCompound input=input(slot,count,damage,existing),before=input.copy(),normalized=TransmitterSlots.normalize(input);if(!input.equals(before))throw new AssertionError("Source normalization mutated input");hash.update(canonical(normalized).getBytes("UTF-8"));cases++;}StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("ffdca89a78e6b2eb8ca88cd54303b15fdd99e3e22b89b58266f3691ee0016ab5"))throw new AssertionError("Actual legacy transmission changed "+out);System.out.println("Actual Screen transmission reference PASS cases="+cases+" sha256="+out);}
 public static NBTTagCompound input(String slot,int count,int damage,int existing){NBTTagCompound root=new NBTTagCompound(),forge=new NBTTagCompound(),modules=new NBTTagCompound(),item=new NBTTagCompound(),settings=new NBTTagCompound();item.setString("id","vandorlabs:redstone_transmitter");item.setByte("Count",(byte)count);item.setShort("Damage",(short)damage);NBTTagCompound itemTag=new NBTTagCompound();itemTag.setIntArray("RedstoneChannels",new int[]{31,32});item.setTag("tag",itemTag);modules.setTag(slot,item);forge.setTag("VandorTransmitters",modules);forge.setString("VandorSharedScreenTransmitter","old");forge.setString("ForeignForge","retain");if(existing!=0){NBTTagCompound main=new NBTTagCompound();main.setIntArray("Channels",existing==1?new int[]{55}:new int[]{-1});settings.setTag("main",main);forge.setTag("VandorTransmission",settings);}root.setTag("ForgeData",forge);root.setInteger("TransmitterSchema",1);root.setString("ForeignRoot","retain");for(String side:new String[]{"RedstonePrimary","RedstoneSecondary"}){NBTTagCompound controls=new NBTTagCompound();NBTTagList rows=new NBTTagList();for(int i=0;i<2;i++){NBTTagCompound row=new NBTTagCompound();row.setString("Label","row"+i);if(existing!=0)row.setIntArray("RedstoneChannels",existing==1?new int[]{55}:new int[]{-1});rows.appendTag(row);}controls.setTag("Rows",rows);root.setTag(side,controls);}return root;}
 private static String canonical(NBTBase tag){if(tag instanceof NBTTagCompound){NBTTagCompound compound=(NBTTagCompound)tag;StringBuilder out=new StringBuilder("{");for(String key:new java.util.TreeSet<String>(compound.getKeySet()))out.append(key).append(':').append(canonical(compound.getTag(key))).append(';');return out.append('}').toString();}if(tag instanceof NBTTagList){NBTTagList list=(NBTTagList)tag;StringBuilder out=new StringBuilder("[");for(int i=0;i<list.tagCount();i++)out.append(canonical(list.get(i))).append(';');return out.append(']').toString();}return tag.toString();}
}
